content.css:
.pbf{background:var(--color-bg-subtle, #fafafa);border-top:1px solid var(--color-border-subtle, #f0f0f0);font-family:var(--font-body, system-ui, sans-serif);color:var(--color-text, #1a1a1a)}
.pbf-inner{max-width:var(--wide-width, 1200px);margin:0 auto;padding:4rem 1.5rem 2rem}
.pbf-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:3rem;margin-bottom:3rem}
.pbf-brand{max-width:280px}
.pbf-logo{font-family:var(--font-heading, inherit);font-size:1.125rem;font-weight:600;color:var(--color-text, #1a1a1a);text-decoration:none}
.pbf-tagline{margin:0.75rem 0 0;font-size:0.875rem;color:var(--color-muted, #8b8b8b);line-height:1.6}
.pbf-heading,.pbf .widget-title{font-size:0.75rem;font-weight:500;text-transform:uppercase;letter-spacing:0.08em;color:var(--color-muted, #8b8b8b);margin:0 0 1rem}
.pbf-links{display:flex;flex-direction:column;gap:0.5rem}
.pbf-links a{color:var(--color-text-secondary, #525252);text-decoration:none;font-size:0.875rem;transition:color 120ms ease}
.pbf-links a:hover{color:var(--color-text, #1a1a1a)}
.pbf .widget-content p{color:var(--color-text-secondary, #525252);font-size:0.875rem;line-height:1.6;margin:0 0 0.5rem}
.pbf-bottom{display:flex;justify-content:space-between;align-items:center;padding-top:1.5rem;border-top:1px solid var(--color-border, #e5e5e5)}
.pbf-copy{font-size:0.875rem;color:var(--color-muted, #8b8b8b);margin:0}
.pbf .theme-switcher{display:flex;gap:0.25rem;padding:0.25rem;background:var(--color-surface, #f7f7f7);border-radius:var(--radius, 4px)}
.pbf .theme-btn{display:flex;align-items:center;justify-content:center;width:30px;height:26px;background:transparent;border:none;color:var(--color-muted, #8b8b8b);border-radius:var(--radius, 4px);cursor:pointer;transition:all 120ms ease}
.pbf .theme-btn:hover{color:var(--color-text-secondary, #525252)}
.pbf .theme-btn.active{background:var(--color-bg, #fff);color:var(--color-text, #1a1a1a)}
@media (max-width:720px){.pbf-grid{grid-template-columns:1fr;gap:2rem}.pbf-bottom{flex-direction:column;gap:1rem}}
